import{_ as s,c as i,o as e,a4 as a}from"./chunks/framework.ssOvXUgL.js";const _=JSON.parse('{"title":"静态资源托管目录","description":"","frontmatter":{},"headers":[],"relativePath":"guide/plugin/public_dirs.md","filePath":"guide/plugin/public_dirs.md","lastUpdated":1728809752000}'),t={name:"guide/plugin/public_dirs.md"},p=a(`<h1 id="静态资源托管目录" tabindex="-1">静态资源托管目录 <a class="header-anchor" href="#静态资源托管目录" aria-label="Permalink to &quot;静态资源托管目录&quot;">​</a></h1><p>默认情况下，框架不会对插件任何目录提供静态资源托管，这意味着无法在诸如 <code>.html</code> 前端文件中直接通过路径来访问指定资源。</p><p>通过配置 <code>publicDirs</code> 配置项，可以声明需要托管静态资源的目录列表，来实现对资源的路径式访问。</p><h2 id="使用示例" tabindex="-1">使用示例 <a class="header-anchor" href="#使用示例" aria-label="Permalink to &quot;使用示例&quot;">​</a></h2><p><code>publicDirs</code> 的值类型为字符串数组，可配置一系列的静态资源的目录路径，需要注意的是，这些路径为相对于 <code>init.ts</code> 的相对路径。</p><p>以插件 <code>example</code> 为例：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> default</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> definePlugin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">( {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // ... other configration</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    publicDirs: [ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;assets/images&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;views&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} );</span></span></code></pre></div><p>这样配置后将对 <code>example/assets/images</code>、<code>example/views</code> 两个目录提供静态资源托管支持。通过 <code>/插件根目录名/资源路径</code> 即可访问目录中的指定资源。</p><p>例如对于 <code>views/index.js</code> 文件，可以通过 <code>/example/views/index.js</code> 路径来正常访问。</p><blockquote><p>需要注意的是，无需专门对 <code>.html</code> 文件配置静态资源托管目录，框架原生支持 <code>.html</code> 文件的读取。但你仍需要为 html 文件中引用的资源提供静态资源托管。</p></blockquote>`,10),l=[p];function n(d,o,c,h,r,k){return e(),i("div",null,l)}const g=s(t,[["render",n]]);export{_ as __pageData,g as default};
